using System.Collections.Generic;

namespace Sexy
{
    /// <summary>
    /// Bookworm's atlas cutter. The art comes as a few big sheets per resolution (Res.IMAGE_GROUP*); one
    /// subclass per resolution (AtlasResourceiPhone, ...iPhoneR, ...iPad, ...iPadR) cuts them into the
    /// sub-images every resolution shares (the tables are in AtlasResources.Data.cs, generated by
    /// tools/gen_atlas.py). BookWormApp's loading thread creates the one for the screen and calls
    /// <see cref="UnpackImages()"/> (vtable slot 2).
    /// </summary>
    public abstract partial class AtlasResourceBase
    {
        /// <summary>The sub-images, indexed as in the generated tables (named accessors in AtlasResources.Data.cs).</summary>
        protected static readonly Image[] mImages = new Image[IMAGE_COUNT];

        /// <summary>Every sub-image cut so far (the vector at 0x1377a4), for freeing them all together.</summary>
        public static readonly List<Image> mAllImages = new List<Image>();

        public abstract void UnpackImages();

        /// <summary>
        /// FUN_0004283c: cuts one sheet. Each row is {image, x, y, w, h, rows, cols, animType, frameDelay,
        /// beginDelay, endDelay}; an animated image gets an AnimInfo computed over max(rows, cols) cels.
        /// </summary>
        protected static void UnpackImages(Image theAtlas, int[,] theTable)
        {
            // Port: the sheets leave 1px (iPad Retina: sometimes none) between entries, so a scaled draw filtered
            // the gap or the neighbour into an entry's edge: 1px seams. The sheet is repacked with a 1px border
            // around each entry copied from its own edge (the sheet itself is never drawn whole).
            List<Microsoft.Xna.Framework.Rectangle> aRects = new List<Microsoft.Xna.Framework.Rectangle>();
            for (int i = 0; i < theTable.GetLength(0); i++)
            {
                aRects.Add(new Microsoft.Xna.Framework.Rectangle(theTable[i, 1], theTable[i, 2], theTable[i, 3], theTable[i, 4]));
            }
            Microsoft.Xna.Framework.Graphics.Texture2D aRepacked = ImageFileLoader.RepackPadded(theAtlas.Texture, aRects, out Microsoft.Xna.Framework.Point[] aPositions);
            if (aRepacked != null)
            {
                Microsoft.Xna.Framework.Graphics.Texture2D anOld = theAtlas.Texture;
                theAtlas.Reset(aRepacked);
                anOld.Dispose();
            }
            for (int i = 0; i < theTable.GetLength(0); i++)
            {
                int aX = aRepacked != null ? aPositions[i].X : theTable[i, 1];
                int aY = aRepacked != null ? aPositions[i].Y : theTable[i, 2];
                Image anImage = new Image(theAtlas, aX, aY, theTable[i, 3], theTable[i, 4]);
                anImage.mNumRows = theTable[i, 5];
                anImage.mNumCols = theTable[i, 6];
                if (theTable[i, 7] != 0)
                {
                    anImage.mAnimInfo = new AnimInfo();
                    anImage.mAnimInfo.mAnimType = (AnimType)theTable[i, 7];
                    anImage.mAnimInfo.mFrameDelay = theTable[i, 8];
                    anImage.mAnimInfo.Compute(System.Math.Max(anImage.mNumRows, anImage.mNumCols), theTable[i, 9], theTable[i, 10]);
                }
                mAllImages.Add(anImage);
                mImages[theTable[i, 0]] = anImage;
            }
        }

        /// <summary>The cutter for a screen's short side, as the loading thread picks it.</summary>
        public static AtlasResourceBase Create(int theScreenSize)
        {
            switch (theScreenSize)
            {
            case 0x600:
                return new AtlasResourceiPadR();
            case 0x300:
                return new AtlasResourceiPad();
            case 0x280:
                return new AtlasResourceiPhoneR();
            default:
                return new AtlasResourceiPhone();
            }
        }
    }
}
